<template><q-dialog v-model="visible" persistent><q-card class="caja-dialog" @keydown="bloquearSignos"><q-card-section class="dialog-head row items-center justify-between"><div class="row items-center no-wrap"><q-avatar :icon="tipo==='abrir'?'lock_open':'lock'" color="green-1" text-color="green-9"/><div class="q-ml-md"><div class="text-h6">{{ titulo }}</div><div class="text-caption text-grey-6">{{ subtitulo }}</div></div></div><q-btn flat round dense icon="close" v-close-popup/></q-card-section><q-card-section><template v-if="tipo==='abrir'"><q-select v-model="form.caja" outlined emit-value map-options label="Caja" :options="cajasDisponibles"/><q-input :model-value="nombreCajero" outlined label="Cajero responsable" readonly class="q-mt-md"/><q-input :model-value="fechaHora" outlined label="Fecha y hora de apertura" readonly class="q-mt-md"/><q-input v-model.number="form.monto" outlined type="number" min="0" label="Monto inicial" prefix="Bs" placeholder="Ej.: 500.00" class="q-mt-md"/><q-input v-model="form.observacion" outlined type="textarea" autogrow label="Observación (opcional)" class="q-mt-md"/></template><template v-else><div class="close-summary"><div><span>Saldo inicial</span><b>Bs {{ dinero(resumen.saldoInicial) }}</b></div><div><span>Ventas en efectivo</span><b>Bs {{ dinero(resumen.efectivo) }}</b></div><div><span>Ventas por QR</span><b>Bs {{ dinero(resumen.qr) }}</b></div><div><span>Ventas mixtas</span><b>Bs {{ dinero(resumen.mixto) }}</b></div><div class="mixed-detail"><span>↳ Efectivo de mixta</span><b>Bs {{ dinero(resumen.mixtoEfectivo) }}</b></div><div class="mixed-detail"><span>↳ QR de mixta</span><b>Bs {{ dinero(resumen.mixtoQr) }}</b></div><div><span>Ventas a crédito</span><b>Bs {{ dinero(resumen.credito) }}</b></div><div class="mixed-detail credit-detail"><span>↳ Efectivo de crédito</span><b>Bs {{ dinero(resumen.creditoEfectivo) }}</b></div><div class="mixed-detail credit-detail"><span>↳ QR de crédito</span><b>Bs {{ dinero(resumen.creditoQr) }}</b></div><div class="expected"><span>Saldo esperado</span><strong>Bs {{ dinero(resumen.esperado) }}</strong></div></div><q-input v-model.number="form.monto" outlined type="number" min="0" label="Efectivo contado" prefix="Bs" placeholder="Ej.: 1250.00" class="q-mt-md"/><div class="difference" :class="diferencia===0?'ok':'warning'"><span><q-icon :name="diferencia===0?'check_circle':'warning'"/> Diferencia</span><strong>{{ diferencia<0?'-':'' }}Bs {{ Math.abs(diferencia).toFixed(2) }}</strong></div><q-input v-model="form.observacion" outlined type="textarea" autogrow label="Observación (obligatoria si hay diferencia)" class="q-mt-md"/></template></q-card-section><q-card-actions align="right" class="dialog-actions"><q-btn flat label="Cancelar" color="grey-7" v-close-popup/><q-btn unelevated color="green-8" :label="tipo==='abrir'?'Confirmar apertura':'Confirmar cierre'" @click="guardar"/></q-card-actions></q-card></q-dialog></template>
<script setup>import{computed,reactive}from'vue';import{useAuthStore}from'../../store/store';const authStore=useAuthStore();const props=defineProps({modelValue:Boolean,tipo:{type:String,required:true},resumen:{type:Object,default:()=>({})},cajas:{type:Array,default:()=>[]}});const emit=defineEmits(['update:modelValue','guardar']);const visible=computed({get:()=>props.modelValue,set:v=>emit('update:modelValue',v)});const cajasDisponibles=computed(()=>props.cajas.length?props.cajas:[{label:'Caja 01',value:1},{label:'Caja 02',value:2},{label:'Caja 03',value:3}]);const form=reactive({caja:1,monto:null,observacion:''});const nombreCajero=computed(()=>authStore.fullName||authStore.getUsername||'Usuario autenticado');const fechaHora=new Date().toLocaleString('es-BO');const diferencia=computed(()=>Number(form.monto||0)-Number(props.resumen.esperado||0));const titulo=computed(()=>props.tipo==='abrir'?'Abrir caja':'Cerrar caja');const subtitulo=computed(()=>props.tipo==='abrir'?'Registra el fondo inicial de la jornada.':'Realiza el arqueo y finaliza la jornada.');function dinero(v){return Number(v||0).toFixed(2)}function bloquearSignos(e){if(e.key==='-'||e.key==='+')e.preventDefault()}function guardar(){if(form.monto==null||Number(form.monto)<0||(props.tipo==='cerrar'&&diferencia.value!==0&&!form.observacion.trim()))return;emit('guardar',{...form,cajero:nombreCajero.value,monto:Number(form.monto),diferencia:diferencia.value});form.monto=null;form.observacion='';visible.value=false}</script>
<style scoped>.caja-dialog{width:520px;max-width:95vw;max-height:90vh;overflow-y:auto;border-radius:17px}.dialog-head{padding:18px 22px;background:#f4faf5;border-bottom:1px solid #e0eee2}.dialog-actions{padding:12px 22px 18px;border-top:1px solid #edf2ee;position:sticky;bottom:0;background:#fff}.close-summary{padding:15px 17px;border:1px solid #dcebe0;border-radius:14px;background:#f7fcf8}.close-summary>div{display:flex;justify-content:space-between;padding:6px 0;color:#627167;font-size:13px}.close-summary b{color:#26352c}.close-summary .mixed-detail{padding:3px 0 3px 12px;color:#829189;font-size:12px}.close-summary .mixed-detail b{color:#627167;font-weight:600}.close-summary .credit-detail{color:#916000}.close-summary .expected{border-top:1px solid #cfe2d4;margin-top:8px;padding-top:13px;color:#176b43;font-weight:800}.close-summary .expected strong{font-size:18px}.difference{display:flex;justify-content:space-between;padding:12px 14px;margin-top:13px;border-radius:10px;font-weight:800}.difference.ok{color:#167345;background:#e7f6ec}.difference.warning{color:#a85f00;background:#fff4df}</style>
